const SITE_ROOT_URL=new URL('.',document.currentScript.src);
const SITE_BASE=decodeURI(SITE_ROOT_URL.pathname).replace(/\/$/,'');
const siteURL=u=>{if(!u.startsWith('/')||u.startsWith('//'))return u;if(location.protocol==='file:'){const relative=u.replace(/^\//,'');const target=new URL(relative,SITE_ROOT_URL);if(!/\.[a-z0-9]+$/i.test(target.pathname)){target.pathname=target.pathname.replace(/\/$/,'')+'/index.html';}return target.href;}return u===SITE_BASE||u.startsWith(SITE_BASE+'/')?u:SITE_BASE+u;};
const rebaseDOM=()=>{document.querySelectorAll('[src],[href],[action]').forEach(el=>{for(const a of ['src','href','action']){const u=el.getAttribute(a);if(u&&u.startsWith('/')&&!u.startsWith('//')){const next=siteURL(u);if(next!==u)el.setAttribute(a,next);}}});};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const A=location.protocol==='file:'?new URL('assets/approved/',SITE_ROOT_URL).href:SITE_BASE+'/assets/approved/';
