function photo(name,rect=[0,0,1,1],alt='',cls='',ratio){if(name==='product-family')return officialPackScene('studio');if(name==='buy-hero')return officialPackScene('cart');const [x,y,w,h]=rect,[nw,nh]=imageSizes[name]||[1500,1000],native=nw*w/(nh*h);return `<figure data-crop="${rect.join(',')}" data-fit="contain" class="crop ${cls}" style="--native-ratio:${native};--ratio:${ratio||native};--iw:${100/w}%;--ih:${100/h}%;--ix:${-x/w*100}%;--iy:${-y/h*100}%"><img decoding="async" src="${A+name}.webp" alt="${esc(alt)}" style="clip-path:inset(${y*100}% ${Math.max(0,1-x-w)*100}% ${Math.max(0,1-y-h)*100}% ${x*100}%)" loading="lazy"></figure>`;}
function hero(tag,title,text,img,rect,extra='',className=''){const [nw,nh]=imageSizes[img],[x,y,w,h]=rect,native=nw*w/(nh*h);return `<section class="hero ${className}"><div class="hero-copy">${eye(tag)}<h1>${title}</h1><p class="lede">${text}</p>${extra}</div><div class="hero-art" style="--hero-ratio:${native}">${photo(img,rect,tag+' editorial image')}</div></section>`;}
const cue=(id,text)=>`<a class="scroll-cue" href="#${id}">${text}<span aria-hidden="true">↓</span></a>`;
const sectionHead=(tag,title,text='',right='')=>`<div class="section-head"><div>${eye(tag)}<h2>${title}</h2>${text?`<p>${text}</p>`:''}</div>${right}</div>`;
function statements(items,numbered=false){return `<div class="statements">${items.map(([h,p],i)=>`<div class="statement ${numbered?'numbered':''}">${numbered?`<b>0${i+1}</b>`:''}<div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>`;}
