function approvedHomeSections(mobile){if(document.body.classList.contains('home-page'))return mobile;return `<div class="approved-home-desktop"><section id="approved-home-nutrition" aria-label="Health, nutrition and everyday movement"><img decoding="async" loading="lazy" src="${A}home-nutrition-approved.webp" width="1586" height="992" alt="Good food. An active life. Enjoy your breakfast. Make time to move. Discover food knowledge and everyday habits for a more balanced routine. Eat with variety. Move in ways you enjoy. Make everyday habits count. A little balance. Every day."><a class="approved-hotspot nutrition-hotspot" href="/health-and-nutrition" aria-label="Explore Health and Nutrition"></a></section><section id="approved-home-story" aria-label="Our story"><img decoding="async" loading="lazy" src="${A}home-story-approved.webp" width="1672" height="941" alt="A Kenyan heritage. A new chapter. From Nakuru beginnings in the 1940s to our home in Limuru today. Our story continues under Astitva Foods in 2026. Nakuru to Nairobi to Limuru. A journey rooted in Kenya."><a class="approved-hotspot story-hotspot" href="/story" aria-label="Discover Our Story"></a></section></div><div class="approved-home-mobile">${mobile}</div>`;}
function approvedHomeField(mobile){if(document.body.classList.contains('home-page'))return homeFieldEditorial();return `<section class="approved-field-desktop" id="approved-home-field" aria-label="From the fields to your table"><img decoding="async" loading="lazy" src="${A}home-field-approved.webp" width="1585" height="992" alt="Before the bowl, there is a field. From the fields. To your table. Every grain begins with the land and the people who tend it. Discover the work, knowledge and growing seasons behind the foods we share. People. Land. Everyday possibilities."><a class="approved-hotspot field-hotspot" href="/farmers" aria-label="Explore Farm to Table"></a></section><div class="approved-field-mobile">${mobile}</div>`;}
function approvedHomePanel(kind,mobile){if(kind==='recipes')return homeRecipeCarousel();if(document.body.classList.contains('home-page'))return mobile;const family=kind==='family';return `<section class="approved-panel-desktop" id="approved-home-${kind}" aria-label="${family?'Good food brings us together':'From our kitchen to yours'}"><img decoding="async" loading="lazy" src="${A}home-${kind}-approved.webp" alt="${family?'Good food brings us together. The first bowl of the day. A slow weekend breakfast. Something baked and shared. Familiar foods become part of the moments we remember. From our home in Kenya to your family’s table.':'A little inspiration. A lot to enjoy. Fresh ideas for familiar favourites. Berry Corn Flakes Bowl. Banana Oat Pancakes. Chocolate Cake.'}">${family?`<a class="approved-hotspot family-hotspot" href="/story" aria-label="Discover Our Story"></a>`:`<a class="approved-hotspot recipe-all-hotspot" href="/recipes" aria-label="Explore All Recipes"></a>${[R[0],R[1],R[3]].map((r,i)=>`<a class="approved-hotspot recipe-item-hotspot recipe-item-${i}" href="/recipes/${r.id}" aria-label="${esc(r.name)}"></a>`).join('')}`}</section><div class="approved-panel-mobile">${mobile}</div>`;}
function homeWhereToBuy(){return `<section class="home-buy" id="feature-buy-hero" aria-labelledby="home-buy-title"><div class="home-buy-main"><div class="home-buy-copy">${eye('WHERE TO BUY')}<h2 id="home-buy-title">Your favourites.<br>Closer to you.</h2><p class="lede">A good morning starts with your favourites. Find Proctor &amp; Allan cereals, oats, porridges and cake mixes at supermarkets and retailers across Kenya.</p>${btn('/where-to-buy','Find a retailer')}<p class="home-buy-note">Look for us in the cereal and baking aisles.</p></div><figure class="home-buy-visual"><img src="/assets/approved/home-shopping-trolley-v4.webp" width="1556" height="1011" loading="lazy" decoding="async" alt="Six Proctor & Allan cartons arranged upright in a shopping trolley: Corn Flakes, White Oats, Quick Porridge Oats, Baby Porridge, Vanilla Cake Mix and Chocolate Cake Mix."></figure></div><div class="home-buy-partners"><div class="home-buy-partners-heading"><span class="eyebrow">FIND US AT YOUR FAVOURITE STORES</span><p>Product ranges and pack sizes vary by branch.</p></div>${retailerLogos()}</div></section>`;}

function home(){document.body.classList.add('home-page');return hero('PROCTOR & ALLAN','Good mornings.<br>Better together.','Wholesome foods for brighter days and everyday moments worth sharing.','home-bowl',[.1,.03,.9,.94],btn('/products','Explore our foods'),'home')+rangeSection()+approvedHomePanel('family',split('MADE FOR THE MOMENTS WE SHARE','Good food brings<br>us together.','The first bowl of the day. A slow weekend breakfast. Something baked and shared. Familiar foods become part of the moments we remember.','family',[0,0,.65,.92],[],false,`${btn('/story','Discover our story')}<p class="feature-caption">From our home in Kenya. To your family’s table.</p>`))+approvedHomeField(split('BEFORE THE BOWL, THERE IS A FIELD','From the fields.<br>To your table.','Every grain begins with the land and the people who tend it. Discover the work, knowledge and growing seasons behind the foods we share.','home-field',[.49,.02,.51,.95],[],true,`${btn('/farmers','Explore farm to table')}<p class="feature-caption">People. Land. Everyday possibilities.</p>`))+approvedHomePanel('recipes',`<section class="section">${sectionHead('THE PROCTOR & ALLAN KITCHEN','A little inspiration.<br>A lot to enjoy.','Fresh ideas with your everyday favourites.',link('/recipes','Explore recipes'))}<div class="recipe-grid">${[R[0],R[1],R[3],R[7]].map(recipeCard).join('')}</div></section>`)+approvedHomeSections(split('HEALTH, NUTRITION & EVERYDAY MOVEMENT','Good food.<br>An active life.','Enjoy your breakfast. Make time to move. Discover food knowledge and everyday habits for a more balanced routine.','home-nutrition',[0,0,.625,1],[],false,`<ul class="everyday-habits"><li>Eat with variety</li><li>Move in ways you enjoy</li><li>Make everyday habits count</li></ul>${btn('/health-and-nutrition','Explore health & nutrition')}<p class="feature-caption">A little balance. Every day.</p>`)+homeHeritage())+homeWhereToBuy()+split('LET’S TALK','Good conversations.<br>New possibilities.','Questions about our foods, retail supply or international opportunities? We’d be glad to hear from you.','contact-hero',[.45,.10,.55,.90],[],true,btn('/contact','Get in touch'));}
function restoredSlide(key,mobile,links=""){if(key==='journey-home-approved'||key==='foods-hero')return mobile;const alts={"foods-hero":"Find your everyday favourite. From the first bowl of the morning to a little home-baked happiness. Discover foods for the moments you make your own.",pancakes:"Banana oat pancakes. Prep 10 minutes. Cook 15 minutes. Serves 2. Ingredients: 100 g White Oats blended into flour, one ripe banana, one egg, 100 ml milk, one teaspoon baking powder and a little oil. Mash banana and whisk with egg and milk. Stir in ground oats and baking powder, rest 5 minutes. Cook small pancakes in a lightly oiled pan for 2 to 3 minutes each side.",chapter:"A new chapter. A familiar name. Under Astitva Foods in 2026. Refreshed packaging, renewed focus on product quality and building the next chapter of a Kenyan food name.","timeline-approved":"A Kenyan story through the years. 1940s: beginnings in Nakuru. 1953: joining Unga. 1998: Unga records sale of Proctor and Allan. 2026: under Astitva Foods.","journey-home-approved":"The journey comes home. From the fields and through production, the journey leads to the foods you choose for your home."};const ext="webp";return `<section class="restored-slide restored-${key}" ${key==='timeline-approved'?'id="journey"':''} aria-label="${esc(alts[key])}"><img decoding="async" loading="lazy" src="${A+key}.${ext}" alt="${esc(alts[key])}">${links}</section><div class="restored-mobile">${mobile}</div>`;}
function timeline(){return timelineMobile().replace('id="journey-mobile"','id="journey"');}
function chapter(){return chapterMobile();}
function foodsHero(){return `<section class="foods-hero-clean" aria-labelledby="foods-hero-title"><img class="foods-hero-background" src="/assets/approved/foods-hero-clean-v2.webp" width="1672" height="941" alt="Corn flakes with fresh fruit, comforting porridge, milk and cake on a bright breakfast table." loading="eager" fetchpriority="high"><div class="foods-hero-copy">${eye('OUR FOODS')}<h1 id="foods-hero-title">Find your<br>everyday favourite.</h1><p class="lede">Crisp cereals, comforting oats, porridge and something to bake. Explore the range and make it your own.</p>${btn('#range','Explore the collection')}</div></section>`;}
function foods(){return foodsHero()+`<section class="section" id="range">${sectionHead('THE PROCTOR & ALLAN COLLECTION','Good food for everyday life.','Five familiar favourites. Find the one that feels like your day.')}<div class="catalogue-tools"><div class="filter-row" aria-label="Filter products">${['All','Corn Flakes','Oats','Porridges','Cake Mix'].map((x,i)=>`<button data-food-filter="${x}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><label class="search-label">Search products<input class="search" type="search" id="product-search" placeholder="Find a favourite…"></label></div>${rangeGrid()}<div class="extra-product"><div><h3>Nutririch Porridge</h3><p class="note">Explore ingredients and product information.</p></div>${link('/products/nutririch-porridge','View details')}</div><p class="note" id="product-status" role="status"></p></section>`+grains()+split('ENJOYING YOUR FAVOURITES','From your cupboard<br>to your table.','A few simple habits for enjoying our foods at home.','storage',[.50,0,.5,1],[['Prepare with confidence','Follow the preparation instructions on your current pack.'],['Keep it fresh','Reseal after opening and follow the storage guidance on the label.'],['Know your pack','Check ingredients, allergens and serving information before use.']],true);}
function recipesPage(){return hero('RECIPES BY PROCTOR & ALLAN','A little inspiration.<br>A lot to enjoy.','Breakfast favourites, simple snacks and bakes worth sharing.','recipes-hero',[.44,.14,.56,.83],btn('#recipe-collection','Discover the recipes'))+`<section class="section" id="recipe-collection">${sectionHead('MADE WITH YOUR FAVOURITES','Something delicious for every day.','Simple ideas with our corn flakes, oats and cake mixes.')}<p class="note">Estimated total times · preparation + cooking</p><div class="catalogue-tools"><div class="filter-row" aria-label="Filter recipes">${['All recipes','Corn Flakes','Oats','Cake Mix'].map((x,i)=>`<button data-recipe-filter="${x}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><label class="search-label">Search recipes<input class="search" id="recipe-search" type="search" placeholder="Recipe or ingredient…"></label></div><div class="recipe-grid" id="recipes-grid">${R.map(recipeCard).join('')}</div><p class="note" role="status" id="recipe-status">Times are estimates. Follow the full recipe and your current pack instructions.</p></section>`+restoredSlide("pancakes",`<section class="section"><div class="recipe-detail">${recipePhoto(R[1])}<div>${eye('IN THE KITCHEN')}<h2>Banana oat pancakes</h2><p class="lede">Made with Proctor & Allan White Oats</p><p class="meta">Prep 10 min · Cook 15 min · Serves 2</p><h3 style="margin-top:30px">What you’ll need</h3><ul>${R[1].ingredients.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Let’s make it</h3><ol>${R[1].steps.map(x=>`<li>${x}</li>`).join('')}</ol><p class="note">Estimated timings. ${R[1].allergens}</p></div></div></section>`)+tips();}
function tips(){return `<section class="section">${sectionHead('A LITTLE KNOW-HOW','Little tips. Better results.','Small details to help you get more from every recipe.')}<div class="ingredient-grid">${[['Blend for a finer texture.','For recipes calling for oat flour, blend the oats finely before measuring.'],['Keep a little crunch.','Crush corn flakes lightly for coatings and toppings, rather than grinding them to powder.'],['Let the recipe guide you.','Preheat the oven and follow your cake mix pack for quantities and baking guidance.']].map(([h,p],i)=>`<article>${photo('tips',[i/3,.29,1/3,.40],h,'',1.5)}<h3 style="font-size:29px">${h}</h3><p>${p}</p></article>`).join('')}</div></section>`;}
function recipeTextDetail(r){return `<section class="section detail-page"><div class="breadcrumb"><a href="/recipes">Recipes</a> / ${r.name}</div><div class="recipe-detail">${recipePhoto(r)}<article>${eye('THE PROCTOR & ALLAN KITCHEN')}<h1>${r.name}</h1><p class="lede">Made with ${r.product}</p><p class="meta">Prep ${r.prep} min · ${r.cook?'Cook '+r.cook+' min':'No cooking'} · Serves ${r.serves}</p><h2>What you’ll need</h2><ul>${r.ingredients.map(x=>`<li>${x}</li>`).join('')}</ul><h2>Let’s make it</h2><ol>${r.steps.map(x=>`<li>${x}</li>`).join('')}</ol><p class="note">${r.note||'Timings are estimates. Follow your current pack instructions.'}</p><p class="note">${r.allergens||'Check every ingredient and your current pack for allergen information.'}</p><button class="print-button" type="button" data-print>Print recipe</button></article></div></section>`;}
function story(){return `<section class="story-heritage-hero" aria-labelledby="story-heritage-title"><div class="story-heritage-copy"><h1 id="story-heritage-title">A Heritage<br>of Good Food.</h1><p>Since 1940, Proctor &amp; Allan has been nourishing families with wholesome foods. Our story is built on quality, care and a commitment to healthier generations.</p><a class="btn" href="#journey">Our Story <span aria-hidden="true">→</span></a></div><figure class="story-heritage-photo"><img src="/assets/approved/story-heritage-restored-v2.webp" width="1939" height="811" alt="Restored archival photograph of the Proctor & Allan building, with vehicles and people outside." loading="eager" fetchpriority="high"></figure></section>`+timeline()+chapter()+storyPerspectives();}
const articles=[
{id:'food-labels',title:'Making sense of food labels',desc:'A guide to ingredients, serving information and nutrition values.',sections:[['Begin with the ingredient list','The ingredients tell you what goes into a food. Read them together with the allergen declaration on the current pack, especially when choosing for someone with an allergy.'],['Check the basis','Before comparing two foods, check whether the values refer to 100 g, a serving or the prepared food. Use the same basis for a fair comparison.'],['Read beyond one number','Look at energy, fibre, sugars, salt and other nutrients together. Product-specific information belongs on the current pack; ask our team if you need clarification.']]},
{id:'varied-breakfast',title:'Building a varied breakfast',desc:'Explore different foods, flavours and textures for your morning.',sections:[['Start with variety','Cereals or porridge can sit alongside other foods in your breakfast routine. Fruit, milk, yoghurt and suitable alternatives offer different flavours and textures.'],['Make it work for you','Choose combinations that fit your preferences, dietary needs and the time you have. A varied diet is about the pattern of what you eat, not one particular breakfast.'],['Know what you add','Milk, sweeteners, fruit and other toppings change the nutrients in your finished meal. Check labels and consider the whole bowl.']]},
{id:'grains',title:'A closer look at grains',desc:'Meet familiar ingredients behind cereals, oats and baking.',sections:[['Different grains, different foods','Maize, oats and wheat can be prepared in many ways. The process and other ingredients help shape the texture and character of the finished food.'],['Read the ingredients','A product name does not tell the whole story. Check the current ingredient list to understand which grains are present and whether a product is described as whole grain.'],['Explore the range','Our range includes maize corn flakes, whole oat products, porridge blends and wheat-based cake mixes. Product pages bring the available ingredient information together.']]},
{id:'your-bowl',title:'What goes into your bowl?',desc:'Consider the milk, fruit and other foods you add.',sections:[['The finished meal matters','Nutrition figures may describe a dry product rather than the bowl you eat. Any milk, yoghurt, fruit, nuts or sweetener you add contributes to the finished meal.'],['Choose your additions','Try different combinations and textures. Check the labels on milk alternatives and other additions rather than assuming that all options have the same nutrients.'],['Keep it clear','Use the serving information and ingredients on your current pack as your starting point. Consider your own needs and preferences when preparing your bowl.']]},
{id:'servings',title:'Servings and portions',desc:'Understand label information and what you serve.',sections:[['Two useful ideas','A serving on a label is the quantity used to describe the product’s nutrition information. Your portion is the amount you actually choose to eat.'],['Check before comparing','Look for the serving weight in grams and whether information is given per 100 g or per serving. Comparing the same quantity helps you understand differences.'],['Consider the full meal','The amount you serve and any additions affect the nutrients in the finished meal. A label serving is not a personalised recommendation.']]},
{id:'active-routine',title:'Food and an active routine',desc:'Make room for enjoyable meals and movement in everyday life.',sections:[['Find movement you enjoy','Walking, cycling, dancing and other forms of movement can have a place in an active routine. Choose activities that suit your ability and circumstances.'],['Food fits into the bigger picture','Enjoy a variety of foods and make time for meals that work for your day. A single cereal or ingredient is not a substitute for a varied diet.'],['Keep it personal','Your needs can change with age, activity and health. Seek individual guidance from a qualified professional if you need support with food or exercise choices.']]}
];
const articleRect=i=>[i%2?.513:.015,[.125,.432,.730][Math.floor(i/2)],.471,[.204,.197,.182][Math.floor(i/2)]];
function articleCard(a,i){return `<article class="article-card"><a href="/health-and-nutrition/${a.id}">${photo('articles',articleRect(i),a.title,'',1.78)}<h3>${a.title}</h3></a><p>${a.desc}</p>${link('/health-and-nutrition/'+a.id,'Explore article')}</article>`;}
function nutritionPage(){return hero('HEALTH & NUTRITION','Good food.<br>An active life.','Explore grains, understand your food and find inspiration for a varied, balanced lifestyle.','nutrition-hero',[.43,.09,.57,.88],cue('nutrition-articles','Discover the goodness within'),'nutrition-blended-hero')+`<section class="section" id="nutrition-articles"><div class="centre" style="margin-bottom:50px">${eye('HEALTH & NUTRITION')}<h2>Food knowledge for everyday life.</h2><p class="lede">Explore grains, breakfast and the information on your pack.</p></div><div class="article-grid">${articles.map(articleCard).join('')}</div></section>`;}
function articleDetail(a){return `<section class="section detail-page"><div class="article-body"><div class="breadcrumb"><a href="/health-and-nutrition">Health & Nutrition</a> / ${a.title}</div>${eye('EVERYDAY FOOD KNOWLEDGE')}<h1>${a.title}</h1><p class="lede">${a.desc}</p>${photo('articles',articleRect(articles.indexOf(a)),a.title,'',1.78)}${a.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<p class="note">General educational information. For product-specific ingredients and nutrition, read your current pack.</p><p class="note">Further reading: <a href="https://www.fda.gov/food/nutrition-facts-label/how-understand-and-use-nutrition-facts-label" target="_blank" rel="noopener">Understanding nutrition labels</a> · <a href="https://www.who.int/news-room/fact-sheets/detail/healthy-diet" target="_blank" rel="noopener">A varied diet</a></p></div></section>`;}
function farmers(){document.body.classList.add('farm-table-page');return `<section class="farm-refined" aria-labelledby="farm-refined-title"><div class="farm-refined-top"><img class="farm-refined-photo" src="/assets/approved/farm-fields-refined-v3.webp" width="1860" height="845" alt="Fresh maize growing in a sunlit field, with green hills and trees beyond." loading="eager" fetchpriority="high"><div class="farm-refined-copy"><h1 id="farm-refined-title">It Begins<br>in Our Fields.</h1><p>We grow quality maize and source the finest ingredients, working closely with farmers to ensure wholesome foods for Kenyan families and beyond.</p><a class="btn" href="#field">Our Farms <span aria-hidden="true">→</span></a></div></div><ol class="farm-refined-stages" aria-label="From our fields to your table">${[['Growing','Healthy crops in our fields'],['Harvesting','At the right time, for best quality'],['Selection','Carefully chosen grains'],['Processing','With modern technology'],['Your Table','Wholesome food for every generation']].map(([title,description],i)=>`<li><span class="farm-stage-number" aria-hidden="true">${i+1}</span><h2>${title}</h2><p>${description}</p></li>`).join('')}</ol></section>`+`<div id="field">${split('WHERE THE JOURNEY BEGINS','The people behind<br>every harvest.','Before grain reaches a mill or a production line, it begins with the knowledge, patience and work of farmers.','farmer',[0,0,.55,.86],[['Growing','Preparing the land and tending the crop through the season.'],['Harvesting','Gathering mature grain for the next stage of its journey.'],['Looking ahead','Recognising the people whose work makes food possible.']])}</div>`+split('THE NEXT STAGE','From grain<br>to food.','Beyond the harvest, preparation, processing and packing shape the foods that reach your table.','manufacturing',[.48,0,.52,1],[['Ingredient preparation','Grains and other ingredients are prepared for the product being made.'],['Processing','Different foods call for different methods, from flaking and milling to blending.'],['Packing','Finished products are packed with information for storage and preparation.']],true)+split('QUALITY & CARE','Care at every stage.','A continued focus on the details that matter, from ingredients to the finished pack.','quality',[0,0,.56,1],[['Ingredient attention','Quality begins with attention to the materials used in each product.'],['Hygiene matters','Clean working practices are central to responsible food production.'],['Packaging with purpose','The finished pack brings together product protection, preparation guidance and useful information.']])+restoredSlide("journey-home-approved",split('TO YOUR TABLE','The journey<br>comes home.','From the fields and through production, the journey leads to the foods you choose for your home.','product-family',[.056,0,.924,1],[],false,`<p class="note">Corn flakes, oats, porridge and cake mixes—each with its own place in everyday life.</p>${btn('/products','Explore our foods')}<p class="note">Farm and production photography illustrates the food journey.</p>`),`<a class="approved-hotspot restored-journey-link" href="/products" aria-label="Explore our foods"></a>`).replace(officialPackScene('studio'),`<figure class="farm-tiered-display"><img src="/assets/approved/farm-tiered-products-refined.webp" width="1374" height="1145" alt="Six Proctor & Allan cereal, oat, porridge and cake mix cartons arranged on two white display tiers." loading="lazy" decoding="async"></figure>`);}
const retailBrands=[['Naivas','retailer-naivas.svg'],['Carrefour','retailer-carrefour.svg'],['Foodplus','retailer-foodplus.svg'],['Quickmart','retailer-quickmart.png'],['Cleanshelf','retailer-cleanshelf-new.png'],['Magunas','retailer-magunas.jpg'],['Jaza · Jazaribu','retailer-jaza.png'],['Greenspoon','retailer-greenspoon.jpg'],['SkyMart Kenya','retailer-skymart-kenya.png']];
function retailerLogos(){const logos=retailBrands.map(([name,file])=>`<div class="retail-brand"><img src="/assets/${file}" alt="${name}" loading="lazy" decoding="async"></div>`).join('');return `<div class="retailer-ribbon" data-retailer-ribbon><div class="retailer-controls"><span>Available across leading retailers</span><button type="button" data-retailer-pause aria-pressed="false">Pause rotation</button></div><div class="retailer-window"><div class="retailer-track"><div class="retailer-set" aria-label="Retailers">${logos}</div><div class="retailer-set" aria-hidden="true">${logos.replaceAll(' alt="',' alt="').replace(/alt="[^"]*"/g,'alt=""')}</div></div></div></div>`;}
function bindRetailerRibbons(){$$('[data-retailer-pause]').forEach(b=>b.addEventListener('click',()=>{const ribbon=b.closest('[data-retailer-ribbon]'),paused=ribbon.classList.toggle('paused');b.setAttribute('aria-pressed',String(paused));b.textContent=paused?'Resume rotation':'Pause rotation';}));}

function whereToBuy(){return `<section class="buy-page-hero" aria-labelledby="buy-page-title"><div class="buy-page-copy">${eye('WHERE TO BUY')}<h1 id="buy-page-title">Your favourites.<br>Closer to you.</h1><p class="lede">Find Proctor &amp; Allan foods at supermarkets and retailers in Kenya.</p><p class="note">Product ranges and pack sizes may vary by store.</p>${cue('retail-partners','Explore our retail partners')}</div><figure class="buy-page-cart"><img src="/assets/approved/home-shopping-trolley-v4.webp" width="1556" height="1011" loading="eager" fetchpriority="high" alt="Proctor & Allan Corn Flakes, White Oats, Quick Porridge Oats, Baby Porridge and vanilla and chocolate cake mixes arranged in a supermarket trolley."></figure></section>`+`<section class="section" id="retail-partners">${sectionHead('AT YOUR LOCAL SUPERMARKET','Find us where you shop.','Look for Proctor & Allan in the cereal and baking aisles.')}${retailerLogos()}<div class="retail-note"><h3>Availability varies by branch.</h3><p>Please check with your preferred store for current products and pack sizes.</p></div><p class="note" style="margin-top:45px">Looking for supply or distribution enquiries? <a href="/contact?topic=business">Contact our team →</a></p></section>`;}
