function fitPhotos(){const fit=f=>{const im=$('img',f);if(!im?.naturalWidth)return;const [x,y,w,h]=f.dataset.crop.split(',').map(Number),nw=im.naturalWidth,nh=im.naturalHeight,cw=f.clientWidth,ch=f.clientHeight;const scale=(f.closest('.home-page .split,.inner-page .split')?Math.max:Math.min)(cw/(nw*w),ch/(nh*h));let left=(cw-nw*w*scale)/2,top=(ch-nh*h*scale)/2;if(f.closest('.hero-art')){left=cw-nw*w*scale;top=0;}else if(f.parentElement.classList.contains('image-left'))left=0;else if(f.parentElement.classList.contains('image-right'))left=cw-nw*w*scale;Object.assign(im.style,{width:nw*scale+'px',height:nh*scale+'px',left:left-nw*x*scale+'px',top:top-nh*y*scale+'px'});};const obs=new ResizeObserver(es=>es.forEach(e=>fit(e.target)));$$('[data-crop]').forEach(f=>{if(f.dataset.fitted)return;f.dataset.fitted='true';const im=$('img',f);im.addEventListener('load',()=>fit(f));obs.observe(f);fit(f);});}
