overnightFlavours.forEach(([slug,name,fruit,flavour,nuts,seeds],i)=>addRecipe(slug+'-overnight-oats',name,'white-oats',['Sweet','Healthy'],5,0,1,['½ cup oats suitable for uncooked soaking','½ cup dairy milk or an unsweetened plant-based milk',fruit,flavour,'1 tbsp chia seeds, optional'],['Check the oat pack permits uncooked soaking. Mix oats, milk and the flavour ingredients in a clean covered container.','Refrigerate for at least 8 hours. If the pack requires cooking, cook with the liquid according to its instructions first, cool promptly and refrigerate instead.','Stir before serving. Add a splash of milk if too thick and choose toppings to suit the eater. Keep refrigerated and eat within 24 hours.'],{chill:480,time:485,ages:nuts||seeds?['Adults']:['Kids','Adults','Older adults'],veganOption:true,gfOption:true,noNutsSeeds:!nuts&&!seeds,nutIncluded:nuts,seedIncluded:seeds,methods:['No cooking'],imageRef:['recipe-poster-1',[.013+(i%3)*.327,i<3?.321:.674,.31,.112]],options:[['Dairy / dairy-free','Use pasteurised dairy milk or an unsweetened plant-based milk. A spoon of dairy or plant yoghurt can be added.'],['Vegan','Choose plant milk and plant yoghurt; leave out honey.'],['Nuts and seeds','For no added nuts or seeds, omit chia, flax, nut butter, nuts and seed toppings. Replace peanut butter with mashed banana; replace almonds with extra berries. Choose an appropriate milk.'],['Older adults','Choose the banana or finely grated apple version with no nuts or seeds. Soften further as preferred. This is not a prescribed texture for swallowing difficulties.']]}));
addRecipe('oat-sourdough-bread','Oat Sourdough Bread','white-oats',['Savoury','Healthy'],20,40,'1 loaf',['1 cup oats','2 cups bread flour','½ cup active sourdough starter','1 cup warm water, plus a little extra if needed','1 tsp salt','1 tbsp honey, optional','2 tbsp seeds, optional'],['Soak the oats in the warm water for 30 minutes.','Mix soaked oats, flour, active starter and salt into a sticky dough. Add a little water only if needed.','Cover and leave to rise until aerated and expanded; this can take 4–6 hours in a warm room. Fermentation depends on the starter and temperature.','Shape and place in a floured basket or bowl. Cover for another 1–2 hours, until ready to bake. An overnight refrigerator rest is an alternative.','Heat the oven and a suitable lidded Dutch oven to 220°C. Bake covered for 20 minutes, then uncovered for about 15–20 minutes, until well baked and the centre reaches about 96°C.','Cool completely before slicing.'],{rest:480,time:540,veganOption:true,dairyOption:false,gfOption:false,methods:['Oven'],imageRef:['recipe-poster-2',[.45,.03,.55,.34]],options:[['Vegan','Omit the optional honey or use maple syrup.'],['With or without seeds','Sprinkle seeds over the loaf if desired, or leave them out entirely.'],['Contains gluten','Bread flour and the wheat starter contain gluten. This recipe cannot be made gluten-free simply by changing the oats.']],allergens:'Contains wheat/gluten; check oats and starter. Seeds are optional.'});
addRecipe('savoury-oat-muffins','Savoury Vegetable Oat Muffins','white-oats',['Savoury','Healthy'],15,25,12,['1½ cups oats, finely blended','½ cup chickpea flour','½ cup plain yoghurt','2 eggs','¼ cup olive oil','½ cup grated carrot','½ cup finely diced capsicum','½ cup chopped spinach','1½ tsp baking powder','1 tsp mixed herbs','¼ cup crumbled feta and 3 tbsp seeds, optional'],['Preheat oven to 180°C and line a 12-hole muffin tin.','Whisk eggs, yoghurt and oil. Stir in blended oats, chickpea flour, baking powder, herbs and vegetables. Add optional feta or seeds if using.','Spoon into the cases and bake for 20–25 minutes, until the centres are set and a skewer comes out clean.','Cool before serving.'],{veganOption:true,gfOption:true,methods:['Oven'],imageRef:['recipe-poster-6',[.47,.035,.53,.27]],options:[['Dairy-free','Use plain plant yoghurt and omit feta or choose a dairy-free alternative.'],['Vegan','Use two prepared flax eggs (2 tbsp ground flax plus 6 tbsp water, rested for 10 minutes), plant yoghurt and no feta. This version contains seeds.'],['No added nuts or seeds','Use eggs rather than flax eggs, omit the seed topping, and use dairy yoghurt or a suitable nut- and seed-free alternative.'],['Gluten-free adaptation','Use explicitly gluten-free oats, chickpea flour and baking powder. Check every other ingredient.']]} );
addRecipe('no-bake-oat-bars','No-Bake Oat Bars','white-oats',['Sweet'],15,0,12,['2 cups oats labelled suitable for uncooked use','½ cup smooth nut butter','½ cup maple syrup','½ cup mixed seeds','½ cup chopped dried fruit','¼ cup dark chocolate chips, optional','1 tsp vanilla'],['Confirm that the oats are suitable for uncooked use; otherwise choose a baked oat recipe.','Mix oats, nut butter, maple syrup, seeds, fruit and vanilla. Press firmly into a lined small tray.','Chill in the refrigerator for 1–2 hours, until firm. Add optional melted chocolate and allow to set.','Slice and store covered in the refrigerator.'],{chill:120,time:135,ages:['Adults'],veganOption:true,gfOption:true,noNutsSeeds:false,nutIncluded:true,seedIncluded:true,methods:['No cooking'],imageRef:['recipe-poster-5',[.46,.05,.54,.26]],options:[['Dairy-free / vegan','Choose dairy-free chocolate and maple syrup; check the nut butter and oats.'],['Nut-free ingredients option','Replace nut butter with sunflower-seed butter and omit nuts. This still contains seeds and is not an allergy-free guarantee.'],['No added seeds','Use smooth nut butter and omit the mixed seeds, adding more suitable oats as needed. This version still contains nuts.']],allergens:'Contains nuts and seeds in the base recipe. Sticky bars are not intended for babies or young children.'});
addRecipe('savoury-quick-oats','Garden Vegetable Quick Oats','quick-oats',['Savoury','Healthy'],5,10,2,['2 servings Quick Porridge Oats','Water according to pack instructions','½ cup finely grated carrot','½ cup finely chopped spinach','1 tsp olive oil','A squeeze of lemon and herbs'],['Gently soften carrot in the oil with a splash of water.','Add spinach and cook until wilted. Prepare oats with water according to the pack, cooking fully.','Stir in the vegetables, herbs and lemon. Add a little water for a softer consistency.'],{veganOption:true,dairyOption:false,gfOption:true,ages:['Kids','Adults','Older adults'],oldPhoto:2,options:[['Dairy addition','Stir in a spoon of plain yoghurt after cooking if desired.'],['Older adults','Cook vegetables until tender and adjust the porridge consistency to preference; individual swallowing needs require tailored advice.']]} );
addRecipe('carrot-banana-porridge','Carrot & Banana Porridge','quick-oats',['Sweet','Healthy'],5,10,2,['2 servings Quick Porridge Oats','Milk or water according to the current pack','½ carrot, finely grated','1 ripe banana, mashed','A pinch of cinnamon, optional'],['Simmer the carrot in a little water until very soft.','Cook oats fully according to the pack using the chosen liquid.','Stir in carrot and mashed banana. Serve warm, adjusting consistency as desired.'],{veganOption:true,gfOption:true,ages:['Kids','Adults','Older adults'],oldPhoto:2,options:[['Dairy-free / vegan','Prepare with water or a suitable unsweetened plant milk.'],['No added nuts or seeds','Serve as written without nut butter or seed toppings.']]} );
addRecipe('oat-vegetable-fritters','Oat & Vegetable Fritters','quick-oats',['Savoury'],15,15,8,['1 cup Quick Porridge Oats','½ cup grated carrot','½ cup grated courgette, squeezed dry','2 eggs','2 tbsp chickpea flour','2 tbsp chopped herbs','Oil for shallow frying'],['Mix oats, vegetables, eggs, flour and herbs. Rest for 10 minutes so the oats hydrate.','Form small, flat fritters. Shallow-fry in a thin layer of oil over medium heat for around 3–4 minutes per side, until the centres are cooked and set.','Drain on kitchen paper and serve warm.'],{veganOption:false,gfOption:true,methods:['Oil fry','Air fryer'],imageRef:['recipe-poster-7',[.67,.59,.31,.10]],options:[['Air fryer','Lightly oil the formed fritters and cook at 180°C for approximately 12–15 minutes, turning halfway, until fully cooked. Use an appliance-approved tray if the mixture is soft.'],['Dairy-free','The recipe contains no dairy ingredient; check pack labels.']]} );
function babyRecipe(id,name,addition,steps){addRecipe(id,name,'baby-porridge',['Healthy'],5,5,'Small baby portion',['Baby Porridge in the quantity stated on the current age-appropriate pack','The preparation liquid and quantity specified on the pack',addition],['Prepare the porridge exactly as the current pack instructs, using clean utensils.',...steps,'Cool and test the temperature. Offer a small amount in an appropriate texture while the baby sits upright and is supervised. Discard food left in the feeding bowl.'],{ages:['Babies'],veganOption:false,dairyOption:false,gfOption:false,oldPhoto:2,note:babyGuidance,options:[['Age and allergens',babyGuidance]],allergens:'Check the baby-porridge label and introduce any new ingredient separately. Do not assume this product is dairy-free or gluten-free.'});}
babyRecipe('baby-banana-porridge','Baby Porridge with Mashed Banana','1–2 tsp smooth ripe banana',['Mash banana very smoothly and stir a little into the prepared porridge. Use only if banana has already been introduced and tolerated.']);
babyRecipe('baby-pear-porridge','Baby Porridge with Soft Pear','1–2 tsp peeled, cooked pear purée',['Steam peeled pear until soft and mash or purée to a suitable texture. Mix a little into the cooked porridge once pear has been introduced and tolerated.']);
babyRecipe('baby-pumpkin-porridge','Baby Porridge with Pumpkin','1–2 tsp fully cooked pumpkin purée',['Cook peeled pumpkin until very soft, then mash or purée. Stir a small amount into the porridge once pumpkin has been introduced and tolerated.']);
addRecipe('nutririch-banana-bowl','Banana Nutririch Bowl','nutririch-porridge',['Sweet','Healthy'],5,10,2,['2 servings Nutririch Porridge','Water in the quantity on the pack','1 ripe banana, mashed'],['Cook Nutririch Porridge completely following the current pack instructions.','Stir in mashed banana and adjust consistency with a little suitable liquid.','Serve warm.'],{veganOption:true,dairyOption:false,gfOption:false,ages:['Kids','Adults','Older adults'],oldPhoto:2,options:[['Dairy addition','Add pasteurised milk or a spoon of yoghurt if desired.'],['Plant-based','Prepare with water and check the current porridge ingredients for animal-derived additions.']],allergens:'Contains soya according to the supplied product information. Check current pack for all allergens.'});
addRecipe('nutririch-pumpkin-bowl','Pumpkin & Cinnamon Nutririch','nutririch-porridge',['Sweet','Healthy'],5,15,2,['2 servings Nutririch Porridge','Water according to pack','½ cup peeled pumpkin, diced','A pinch of cinnamon'],['Cook pumpkin in water until very soft and mash.','Prepare Nutririch according to the current pack, cooking fully.','Stir in pumpkin and cinnamon. Serve warm.'],{veganOption:true,dairyOption:false,ages:['Kids','Adults','Older adults'],oldPhoto:2,allergens:'Contains soya. Check the current pack.',options:[['Dairy option','Finish with a spoon of plain dairy yoghurt if desired.']]} );
addRecipe('nutririch-savoury-vegetables','Savoury Vegetable Nutririch','nutririch-porridge',['Savoury','Healthy'],10,15,2,['2 servings Nutririch Porridge','Water according to pack','½ cup finely grated carrot','½ cup chopped spinach','1 tsp oil','Chopped herbs'],['Soften carrot in oil and a splash of water. Add spinach and cook until tender.','Cook Nutririch fully according to the current pack.','Stir through the vegetables and herbs. Adjust consistency with water and serve.'],{veganOption:true,dairyOption:false,ages:['Kids','Adults','Older adults'],oldPhoto:2,allergens:'Contains soya. Check the current pack.'});
addRecipe('cornflake-chevda','Corn Flakes Chevda','cornflakes',['Savoury','Festive'],10,12,5,['4 cups Corn Flakes','¼ cup peanuts','¼ cup roasted chana dal','¼ cup cashews','2 tbsp pumpkin seeds and 2 tbsp sunflower seeds','8 curry leaves','½ tsp turmeric','A little chilli powder, optional','2 tbsp cooking oil'],['Heat oil gently in a wide pan. Add nuts and roasted chana dal and stir until golden; avoid burning.','Add curry leaves carefully and cook briefly, then stir in turmeric and optional chilli.','Add corn flakes and seeds. Toss over low heat for 2–3 minutes until crisp.','Cool completely before serving. Store in a clean airtight container and use promptly.'],{ages:['Adults'],veganOption:true,dairyOption:false,gfOption:true,noNutsSeeds:false,nutIncluded:true,seedIncluded:true,methods:['Oil fry','Air fryer'],imageRef:['recipe-poster-8',[.46,.055,.34,.19]],options:[['Air-fryer variation','Use an appliance-approved heatproof dish to contain the mixture. Toast the nuts separately at about 160°C for 5–8 minutes, checking and stirring often. Toss corn flakes with a little oil and the cooked spice mixture, then warm briefly in the dish at 150°C, checking every minute. Follow the appliance instructions. Do not put loose lightweight flakes or curry leaves directly into an air-fryer basket: airflow can lift them toward the heater.'],['No added nuts or seeds','Omit peanuts, cashews and all seeds; use extra roasted chana dal and corn flakes. Check the chana dal is suitable for your ingredient exclusions.'],['Gluten-free adaptation','Use corn flakes and all other ingredients explicitly labelled gluten-free. Ordinary corn flakes may contain barley malt.']]} );
addRecipe('cornflake-yoghurt-cups','Fruit & Corn Flake Yoghurt Cups','cornflakes',['Sweet','Healthy'],10,0,2,['60 g Corn Flakes','200 g plain yoghurt','1 banana, sliced','½ cup washed soft berries'],['Spoon yoghurt into two glasses or bowls.','Add fruit and finish with corn flakes just before serving so they stay crisp.','For young children, mash or cut fruit appropriately and soften the flakes in yoghurt.'],{veganOption:true,gfOption:true,ages:['Kids','Adults'],oldPhoto:0,methods:['No cooking'],options:[['Dairy-free / vegan','Use plain unsweetened plant yoghurt with a suitable ingredient list.'],['Nuts and seeds','Serve plain, or add nuts and seeds for adults. Keep whole nuts away from children under five.']]} );
addRecipe('cornflake-vegetable-cutlets','Corn Flake Vegetable Cutlets','cornflakes',['Savoury'],15,15,6,['2 cooked potatoes, mashed','½ cup cooked peas and finely grated carrot','60 g Corn Flakes, crushed','2 tbsp chickpea flour','2 tbsp water, plus more if needed','1 tbsp herbs','Oil for shallow frying'],['Mix potato, cooked vegetables and herbs. Shape into six small patties.','Mix chickpea flour with water to make a thin paste. Dip patties and cover with crushed corn flakes.','Shallow-fry over medium heat in a little oil, turning until golden and steaming hot throughout. Serve warm.'],{veganOption:true,dairyOption:false,gfOption:true,methods:['Oil fry','Air fryer'],imageRef:['recipe-poster-7',[.67,.59,.31,.10]],options:[['Air fryer','Lightly oil the coated patties. Cook in a single layer at 180°C for around 12–15 minutes, turning halfway, until hot throughout.'],['Gluten-free adaptation','Use explicitly gluten-free corn flakes and chickpea flour. Check every ingredient.']]} );
addRecipe('cake-popsicles','Celebration Cake Popsicles','cake-mix',['Sweet','Festive'],15,30,10,['Vanilla or Chocolate Cake Mix','Additional ingredients according to pack','2–3 tbsp frosting, enough to bind','200 g melting chocolate','Sprinkles, optional'],['Bake the cake according to the pack and cool completely.','Crumble the cooled cake. Add frosting a spoon at a time until the mixture holds together.','Press into food-safe popsicle moulds and chill until firm. Dip in melted chocolate and decorate.','Allow the coating to set. Remove sticks before serving to young children.'],{chill:60,time:105,methods:['Oven'],imageRef:['recipe-poster-0',[.49,.045,.39,.30]],options:[['Dairy-free option','Only where the cake mix itself contains no milk: use the pack-approved dairy-free additions, dairy-free frosting and chocolate. Check all labels.'],['No added nuts or seeds','Use plain chocolate and decorations without nuts or seeds, checking all ingredient labels.']],note:'Allow additional cooling time. Make with the current official cake mix; packaging shown in the supplied concept poster is not used as product information.'});
addRecipe('diwali-thandai-cake','Diwali Thandai Cake','cake-mix',['Sweet','Festive'],20,35,10,['Vanilla Cake Mix and additional ingredients according to its pack','3 tbsp finely ground thandai powder made with almonds, pistachios, fennel, melon seeds and cardamom','1 cup whipping cream','Edible rose petals and finely chopped nuts, optional'],['Prepare the cake batter following the current pack. Fold in the thandai powder and bake at the pack temperature until the centre is baked; allow roughly 30–35 minutes if using suitable sandwich tins.','Cool completely. Whip the cream and spread between and over the cake layers.','Finish with food-grade edible rose petals and finely chopped nuts if desired. Chill until serving.'],{time:55,methods:['Oven'],noNutsSeeds:false,nutIncluded:true,seedIncluded:true,imageRef:['recipe-poster-4',[.41,.065,.43,.30]],options:[['Dairy-free option','Only if the mix itself is milk-free: use the pack-approved dairy-free additions and plant whipping cream.'],['No added nuts or seeds variation','Do not use thandai powder. Flavour with cardamom and a little food-grade rose water instead, and leave off all nuts and seeds. This is a rose-cardamom variation, not traditional thandai.']],allergens:'Contains nuts and seeds in thandai powder; cake mix may contain wheat, milk or egg. Check all labels.',note:'The estimate excludes cooling, decorating and chilling. Cake-mix instructions take priority.'});
R[7].gfOption=false;
R.forEach(r=>{r.productIds ||= [r.productId];r.options ||= [];r.ages ||= ['Adults'];r.methods ||= ['Stovetop'];r.categories ||= ['Sweet'];});
function recipeDuration(r){if(r.durationLabel)return r.durationLabel;const rest=r.rest?` · Rest ${r.rest>=60?r.rest/60+' h':r.rest+' min'}`:'';const chill=r.chill?` · Chill ${r.chill>=60?r.chill/60+' h':r.chill+' min'}`:'';return `Prep ${r.prep} min${r.cook?' · Cook '+r.cook+' min':''}${rest}${chill}`;}
function recipePhoto(r,cls=''){if(r.imageRef)return photo(r.imageRef[0],r.imageRef[1],r.name+' serving suggestion',cls,1.36);const i=r.oldPhoto??Math.max(0,Math.min(7,R.indexOf(r)));return photo('recipes',recipeRect(i),r.name+' serving suggestion',cls,1.36);}
function recipeCard(r){return `<a class="recipe-card" href="/recipes/${r.id}">${recipePhoto(r)}<div class="recipe-title"><h3>${r.name}</h3><span class="circle" aria-hidden="true">→</span></div><p class="meta">${r.categories.slice(0,2).join(' · ')}${r.veganOption?' · Vegan option':''}</p>${r.poster?'<span class="recipe-guide-label">Illustrated recipe guide →</span>':''}<p class="recipe-timing">${recipeDuration(r)}</p><p class="recipe-age">${r.ages.join(' · ')}${r.ages.includes('Babies')?' · around 6m+, pack guidance':''}</p></a>`;}
function recipeMatches(r,f={}){return (!f.product||r.productIds.includes(f.product))&&(!f.category||r.categories.includes(f.category)||(f.category==='Vegan'&&r.veganOption)||(f.category==='Vegetarian'&&r.vegetarian))&&(!f.age||r.ages.includes(f.age))&&(!f.diet||(f.diet==='vegan'&&r.veganOption)||(f.diet==='vegetarian'&&r.vegetarian)||(f.diet==='nonveg'&&r.nonveg)||(f.diet==='gf'&&r.gfOption)||(f.diet==='dairy'&&r.dairyOption)||(f.diet==='dairy-free'&&(r.dairyOption||(!r.ages.includes('Babies')&&r.productId!=='cake-mix'))))&&(!f.exclusion||(f.exclusion==='no-added'&&r.noNutsSeeds)||(f.exclusion==='nuts'&&r.nutIncluded)||(f.exclusion==='seeds'&&r.seedIncluded))&&(!f.method||r.methods.includes(f.method))&&(!f.q||(r.name+' '+r.product+' '+r.ingredients.join(' ')+' '+r.categories.join(' ')).toLowerCase().includes(f.q.toLowerCase()));}
function recipeGroups(list,selected=''){return recipeProducts.filter(p=>!selected||p.id===selected).map(p=>{const group=list.filter(r=>r.productIds.includes(p.id));if(!group.length)return '';return `<section class="recipe-product-group" aria-label="${p.name} recipes"><div class="recipe-group-title"><div><span class="eyebrow">MADE WITH ${p.name.toUpperCase()}</span><h3>${p.name} recipes</h3></div><span>${group.length} ideas</span></div><div class="recipe-grid">${group.map(recipeCard).join('')}</div></section>`;}).join('')||'<div class="recipe-empty"><h3>No recipes match these choices.</h3><p>Try another product or reset one of the filters.</p></div>';}
function librarySelect(id,label,values){return `<label>${label}<select id="${id}" data-library-select><option value="">All ${label.toLowerCase()}</option>${values.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;}
function recipeLibrary(){return `<section class="section recipe-library" id="recipe-collection">${sectionHead('START WITH YOUR FAVOURITE','One product.<br>So many possibilities.','Choose your product, then explore sweet, savoury, healthy and festive ideas for the people you cook for.')}<div class="recipe-product-tabs" role="group" aria-label="Choose a recipe product"><button data-library-product="" aria-pressed="true"><span>All products</span><small>${R.length} recipes</small></button>${recipeProducts.map(p=>`<button data-library-product="${p.id}" aria-pressed="false"><span>${p.name}</span><small>${R.filter(r=>r.productIds.includes(p.id)).length} recipes</small></button>`).join('')}</div><div class="filter-row recipe-category-tabs" role="group" aria-label="Recipe category">${['All categories','Sweet','Savoury','Healthy','Vegan','Vegetarian','Festive'].map((c,i)=>`<button data-library-category="${i?c:''}" aria-pressed="${!i}">${c}</button>`).join('')}</div><div class="recipe-refine">${librarySelect('recipe-age','Age groups',[['Kids','Kids'],['Adults','Adults'],['Babies','Babies · around 6m+'],['Older adults','Older adults']])}${librarySelect('recipe-diet','Dietary options',[['vegetarian','Vegetarian'],['vegan','Vegan option'],['nonveg','Non-vegetarian'],['gf','Gluten-free adaptation'],['dairy','Dairy / dairy-free choice'],['dairy-free','Dairy-free option']])}${librarySelect('recipe-exclusion','Nuts and seeds',[['no-added','No added nuts or seeds'],['nuts','Nuts included'],['seeds','Seeds included']])}${librarySelect('recipe-method','Cooking methods',['Air fryer','Oil fry','Oven','Stovetop','Pan cook','No cooking'].map(x=>[x,x]))}<label class="recipe-library-search">Search<input type="search" id="recipe-library-search" placeholder="Recipe or ingredient…"></label></div><div class="recipe-results-bar"><p id="recipe-library-status" role="status">${R.length} recipes · grouped by product</p><button id="recipe-library-reset" class="text-link">Reset filters ↺</button></div><p class="recipe-context" id="recipe-context">Dietary labels describe the listed recipe or its explained variation. Check the recipe and current product labels before choosing ingredients.</p><div id="recipe-library-results">${recipeGroups(R)}</div><details class="recipe-guidance"><summary>Dietary options, age groups and ingredient checks</summary><p>${gfGuidance}</p><p>${allergyGuidance}</p><p>Age groups are recipe inspiration, not a personalised nutrition or swallowing assessment. For young children, serve an appropriate texture and avoid whole nuts. Older adults with swallowing difficulties need individually prescribed textures.</p><p>${babyGuidance}</p><p>Timings are estimates. Your current pack instructions and appliance directions take priority.</p></details></section>`;}
function bindRecipeLibrary(){if(!$('#recipe-library-results'))return;const f={};const apply=()=>{const list=R.filter(r=>recipeMatches(r,f));$('#recipe-library-results').innerHTML=recipeGroups(list,f.product);$('#recipe-library-status').textContent=`${list.length} ${list.length===1?'recipe':'recipes'}${f.product?' with '+recipeProducts.find(p=>p.id===f.product).name:' · grouped by product'}`;$('#recipe-context').textContent=f.age==='Babies'?babyGuidance:f.diet==='gf'?gfGuidance:f.exclusion==='no-added'?allergyGuidance:'Dietary labels describe the recipe or its explained variation. Check the full recipe and your current ingredient labels.';fitPhotos();};$$('[data-library-product]').forEach(b=>b.addEventListener('click',()=>{f.product=b.dataset.libraryProduct;$$('[data-library-product]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));apply();}));$$('[data-library-category]').forEach(b=>b.addEventListener('click',()=>{f.category=b.dataset.libraryCategory;$$('[data-library-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));apply();}));for(const [id,key] of [['recipe-age','age'],['recipe-diet','diet'],['recipe-exclusion','exclusion'],['recipe-method','method']])$('#'+id).addEventListener('change',e=>{f[key]=e.target.value;apply();});$('#recipe-library-search').addEventListener('input',e=>{f.q=e.target.value;apply();});$('#recipe-library-reset').addEventListener('click',()=>{for(const k of Object.keys(f))delete f[k];$$('[data-library-product],[data-library-category]').forEach(b=>b.setAttribute('aria-pressed',String(!(b.dataset.libraryProduct||b.dataset.libraryCategory))));$$('[data-library-select],#recipe-library-search').forEach(e=>e.value='');apply();});const initial=new URLSearchParams(location.search).get('product');if(recipeProducts.some(p=>p.id===initial))$(`[data-library-product="${initial}"]`).click();}
function recipeTextDetail(r){return `<section class="section detail-page"><div class="breadcrumb"><a href="/recipes">Recipes</a> / <a href="/recipes?product=${r.productId}">${products.find(p=>p.id===r.productId).name}</a> / ${r.name}</div><div class="recipe-detail">${recipePhoto(r)}<article>${eye('THE PROCTOR & ALLAN KITCHEN')}<h1>${r.name}</h1><p class="lede">Made with ${r.product}</p><p class="meta">${recipeDuration(r)} · Makes / serves ${r.serves}</p><div class="recipe-badges">${[...r.categories,...r.ages,...(r.veganOption?['Vegan option']:[]),...(r.gfOption?['Gluten-free adaptation']:[])].map(x=>`<span>${x}</span>`).join('')}</div><h2>What you’ll need</h2><ul>${r.ingredients.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Let’s make it</h2><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${r.options.length?`<h2>Make it your way</h2><div class="recipe-options">${r.options.map(([h,p])=>`<section><h3>${h}</h3><p>${p}</p></section>`).join('')}</div>`:''}${r.gfOption?`<p class="note">${gfGuidance} <a href="${recipeSafetySources.gluten}" target="_blank" rel="noopener">About gluten-free oats ↗</a></p>`:''}<p class="note">${r.note||'Timings are estimates. Follow your current pack and appliance instructions.'}</p><p class="note">${r.allergens||'Check every ingredient and your current pack for allergens.'} ${allergyGuidance}</p>${r.ages.includes('Babies')?`<p class="note"><a href="${recipeSafetySources.baby}" target="_blank" rel="noopener">Baby feeding guidance ↗</a></p>`:''}${r.nonveg?`<p class="note"><a href="${recipeSafetySources.cooking}" target="_blank" rel="noopener">Safe cooking temperatures ↗</a></p>`:''}<button class="print-button" type="button" data-print>Print recipe</button></article></div><div class="recipe-back">${btn('/recipes?product='+r.productId,'More '+products.find(p=>p.id===r.productId).name+' recipes',true)}</div></section>`;}
function recipesPage(){return hero('RECIPES BY PROCTOR & ALLAN','A little inspiration.<br>A lot to enjoy.','Start with your favourite product. Find a recipe for your table, your occasion and your way of eating.','recipes-hero',[.44,.14,.56,.83],btn('#recipe-collection','Find your recipe'))+recipeLibrary()+illustratedRecipeFeature()+tips();}

function productDetail(p){const ideas=R.filter(r=>r.productIds.includes(p.id));return baseProductDetail(p)+(ideas.length?`<section class="section product-recipe-ideas">${sectionHead('IN YOUR KITCHEN','More ways to enjoy '+p.name+'.','Explore sweet, savoury and seasonal ideas with this product.',link('/recipes?product='+p.id,'All '+p.name+' recipes'))}<div class="recipe-grid">${ideas.slice(0,3).map(recipeCard).join('')}</div></section>`:'');}

