const sourdoughRecipe=R.find(r=>r.id==='oat-sourdough-bread');
Object.assign(sourdoughRecipe,{durationLabel:"Prep 20 min · Ferment 8–12 h · Proof 1–2 h · Bake 35–40 min",rest:660,time:720,ingredients:['1 cup White Oats or Quick Porridge Oats, whole or lightly blended','1½ cups bread flour','½ cup active sourdough starter','1 cup warm water, plus extra if needed','2 tbsp olive oil','1 tbsp honey or maple syrup, optional','1 tsp salt','3–4 tbsp mixed sunflower, pumpkin, flax and chia seeds, optional'],steps:['Mix the oats with warm water and leave for 20–30 minutes to soften.','Combine the soaked oats, bread flour, active starter, oil, salt, optional sweetener and seeds. Mix into a sticky dough; add a little water only if needed.','Cover and ferment until expanded and airy, approximately 8–12 hours depending on temperature and starter activity.','Shape into a loaf and proof in a floured basket or bowl for 1–2 hours, until ready to bake.','Preheat the oven and an oven-safe lidded Dutch oven to 220°C. Bake covered for 20 minutes, then uncovered for about 15–20 minutes, until well baked.','Cool completely before slicing.'],options:[['Contains gluten','Wheat flour and a wheat-based sourdough starter contain gluten. The flour swap shown on the supplied poster does not by itself make this recipe gluten-free. Use a separately validated gluten-free bread recipe, gluten-free starter and explicitly gluten-free oats if required.'],['Dairy-free','No dairy ingredient is required in this recipe. Check all pack labels.'],['Vegan','Use maple syrup or omit the optional sweetener; choose a starter and ingredients without animal-derived additions.'],['Seeds optional','For no added seeds, omit the seed blend and do not add a seed topping. Check labels and cross-contact separately.']],allergens:'Contains wheat/gluten. Oats and optional seeds must be checked against the current labels.',note:'Prep 20 minutes, plus a 20–30 minute oat soak, an estimated 8–12 hour fermentation, 1–2 hour final proof, baking and cooling. Fermentation is guided by the dough, not the clock.'});


Object.assign(R.find(r=>r.id==='no-bake-oat-bars'),{steps:['Mix suitable ready-to-eat oats with nut butter, maple syrup, seeds, dried fruit and vanilla until evenly coated.','Press firmly and evenly into a lined small tray.','Cover and refrigerate for 1–2 hours until firm.','Lift from the tray and slice into bars.','If using chocolate, drizzle it over the bars and let it set in the refrigerator.'],note:'Use oats explicitly suitable for uncooked recipes. If the pack requires cooking, choose a baked oat recipe instead. Keep these bars refrigerated.'});
Object.assign(R.find(r=>r.id==='cake-popsicles'),{chill:30,time:75,ingredients:['Cake Mix and additional ingredients according to the current pack','½ cup cream cheese or suitable frosting, added gradually as needed','200 g melting chocolate','Sprinkles or other suitable decorations, optional'],steps:['Bake according to the cake-mix pack. Cool completely, then crumble into fine pieces.','Add cream cheese or frosting a spoon at a time until the cake mixture holds together.','Press into small food-safe popsicle moulds or shapes. Insert sticks if using and place on a lined tray.','Melt the chocolate gently. Dip each cake shape, let excess chocolate drip off and place on the tray.','Decorate while the coating is wet. Refrigerate for 20–30 minutes until set. Remove sticks before serving to young children.']});
R.find(r=>r.id==='diwali-thandai-cake').steps=['Prepare the batter according to the current vanilla cake-mix pack and fold in the thandai powder.','Bake using the pack temperature and timing, checking the centre is baked. Cool the cakes completely.','Whip the cream for the frosting. Use a suitable plant whipping cream for the conditional dairy-free version.','Spread cream between the cooled cake layers, stack and cover with the remaining cream.','Finish with optional finely chopped nuts and food-grade edible rose petals. Refrigerate until serving.'];
R.find(r=>r.id==='savoury-oat-muffins').steps=['Blend the oats into a fine flour. Preheat the oven to 180°C and line a 12-hole muffin tin.','Whisk eggs, yoghurt and oil together.','Stir in the oat flour, chickpea flour, baking powder, herbs and vegetables. Add optional feta or seeds if using; mix just until combined.','Divide between the lined muffin cases.','Bake for 20–25 minutes, until the centres are set and a skewer comes out clean.','Let the muffins cool before serving.'];
R.find(r=>r.id==='cornflake-chevda').steps=['Heat oil gently in a wide pan. Add nuts and roasted chana dal and stir until golden. Remove and keep aside.','Add the curry leaves carefully to the pan and cook briefly.','Reduce the heat and stir in turmeric and optional chilli.','Add the corn flakes and toss over low heat for 2–3 minutes, until crisp.','Stir in the toasted nuts, chana dal and seeds.','Cool completely before serving. Store in a clean airtight container and use promptly.'];

