function recipeTimingStrip(r){const entries=[['Preparation',r.prep+' min'],...(r.id==='oat-sourdough-bread'?[['Fermentation','8–12 hours'],['Final proof','1–2 hours']]:r.rest?[['Resting',r.rest/60+' hours']]:[]),...(r.chill?[['Chilling',r.chill>=60?r.chill/60+' hours':r.chill+' min']]:[]),...(r.cook?[['Cooking',r.id==='oat-sourdough-bread'?'35–40 min':r.cook+' min']]:[]),['Makes / serves',String(r.serves)]];return `<div class="integrated-recipe-timings">${entries.map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`;}
function recipeDetail(r){const art=recipeIllustrations[r.id];return `<section class="integrated-recipe detail-page"><div class="integrated-recipe-crumb"><a href="/recipes">Recipes</a> / <a href="/recipes?product=${r.productId}">${products.find(p=>p.id===r.productId).name}</a></div><div class="integrated-recipe-hero"><div class="integrated-recipe-intro">${eye('PROCTOR & ALLAN · THE RECIPE KITCHEN')}<h1>${r.name}</h1><p class="lede">${art?.description||'Made with '+r.product+'. Follow the ingredients and method below, then choose the variation that suits your table.'}</p><div class="recipe-badges">${r.categories.map(x=>`<span>${x}</span>`).join('')}${r.veganOption?'<span>Vegan option</span>':''}</div><a class="text-link" href="#recipe-method">Let’s make it ↓</a></div>${recipeHeroArt(r)}</div>${recipeTimingStrip(r)}<div class="integrated-recipe-body"><aside class="recipe-ingredients" aria-labelledby="ingredients-title"><h2 id="ingredients-title">Ingredients</h2><p class="ingredient-check-hint">Tick off as you prepare.</p><ul>${r.ingredients.map((text,i)=>{const pic=ingredientPicture(text);return `<li class="${pic?'with-picture':'without-picture'}"><label><input type="checkbox" data-ingredient-check aria-label="Prepared: ${esc(text)}"><span class="ingredient-check-mark" aria-hidden="true"></span>${pic?photo(pic.source,pic.rect,text+' — ingredient illustration','ingredient-picture',1.2):''}<span class="ingredient-text">${esc(text)}</span></label></li>`;}).join('')}</ul></aside><article class="recipe-method" id="recipe-method" aria-labelledby="method-title"><h2 id="method-title">Method</h2><ol>${r.steps.map((text,i)=>`<li><span class="method-number" aria-hidden="true">${i+1}</span>${art?.steps[i]?photo(art.source,art.steps[i],(art.titles[i]||'Step '+(i+1))+' — preparation photograph','method-picture',1.65):''}<div class="method-instruction">${art?.titles[i]?`<h3>${art.titles[i]}</h3>`:''}<p>${esc(text)}</p></div></li>`).join('')}</ol></article></div>${art?.servings?`<section class="integrated-serving-ideas"><h2>Serving ideas</h2><div>${art.servings.map((caption,i)=>`<figure>${photo(art.source,[.59+i*.10,.916,.095,.052],caption,'serving-picture',1.2)}<figcaption>${caption}</figcaption></figure>`).join('')}</div></section>`:''}${r.options.length?`<section class="integrated-recipe-options"><h2>Make it your way</h2><div>${r.options.map(([title,text])=>`<section><h3>${title}</h3><p>${text}</p></section>`).join('')}</div></section>`:''}<div class="integrated-recipe-notes"><p>${r.note||'Timings are estimates. Follow your current pack and appliance instructions.'}</p><p>${r.allergens||'Check the current product pack and every ingredient for allergens.'} ${allergyGuidance}</p>${r.gfOption?`<p>${gfGuidance}</p>`:''}${r.ages.includes('Babies')?`<p>${babyGuidance}</p>`:''}</div><div class="integrated-recipe-actions">${btn('/recipes?product='+r.productId,'More '+products.find(p=>p.id===r.productId).name+' recipes',true)}<button class="print-button" type="button" data-print>Print this recipe</button></div></section>`;}
function illustratedRecipeFeature(){const r=sourdoughRecipe;return `<section class="section integrated-recipe-feature"><div>${eye('FROM THE RECIPE KITCHEN')}<h2>A loaf to make<br>your own.</h2><p class="lede">Follow the pictured ingredients and illustrated steps, then choose how you serve it.</p>${btn('/recipes/'+r.id,'Make oat sourdough')}</div>${recipeHeroArt(r)}</section>`;}

