addRecipe('cornflake-energy-bars','Corn Flakes Energy Bars','cornflakes',['Sweet'],15,0,'12 bars',['3 cups Corn Flakes','½ cup peanut or almond butter','⅓ cup honey or date syrup','½ cup mixed nuts','2 tbsp chia, flax or sunflower seeds','½ cup dried fruit'],['Mix all ingredients in a bowl until evenly coated.','Press firmly into a lined tray.','Refrigerate for 1–2 hours until firm. Cut into bars and keep refrigerated.'],{chill:120,nutIncluded:true,seedIncluded:true,noNutsSeeds:false,ages:['Adults'],methods:['No cooking'],options:[['Vegan option','Choose date syrup and check every ingredient.']],poster:'recipe-poster-7'});
addRecipe('cornflake-trail-mix','Corn Flakes Trail Mix','cornflakes',['Sweet'],5,0,'6 servings',['3 cups Corn Flakes','½ cup mixed nuts','2 tbsp pumpkin or sunflower seeds','⅓ cup dried fruit','A pinch of cinnamon, optional'],['Combine the corn flakes, nuts, seeds and dried fruit in a large bowl.','Sprinkle with cinnamon if using and mix gently.','Keep in a clean airtight container.'],{nutIncluded:true,seedIncluded:true,noNutsSeeds:false,ages:['Adults'],methods:['No cooking'],poster:'recipe-poster-7',options:[['No added nuts or seeds','Omit the nuts and seeds and add extra corn flakes and dried fruit. Check ingredient labels.']]});
addRecipe('cornflake-paneer-bites','Corn Flakes Paneer Bites','cornflakes',['Savoury'],10,15,'12 bites',['2 cups Corn Flakes, crushed','200 g paneer, cubed','⅓ cup chickpea flour or oat flour','Water, enough to make a coating batter','1 tsp herbs','Salt and pepper to taste','1 tbsp olive oil'],['Mix flour with enough water to make a coating batter. Season with herbs, salt and pepper.','Dip paneer cubes in the batter, then roll in crushed corn flakes.','Pan-fry with a little oil, turning until golden and hot throughout.','Serve warm with your favourite dip.'],{methods:['Oil fry','Air fryer'],dairyOption:false,poster:'recipe-poster-7',allergens:'Contains milk from paneer. Check corn flakes and flour labels.',options:[['Air fryer','Lightly oil the coated paneer and cook in a single layer, following your appliance instructions and checking until golden and hot throughout.'],['Dairy-free variation','Use firm tofu instead of paneer; check for soya and other allergens.']]});
addRecipe('cornflake-dessert-cups','Corn Flakes Dessert Cups','cornflakes',['Sweet'],10,0,'4 servings',['2 cups Corn Flakes','1 cup whipped cream or coconut cream','½ cup melted dark chocolate or dairy-free chocolate','Fresh fruit and nuts for topping'],['Layer corn flakes, cream and fruit in four cups.','Drizzle with melted chocolate.','Top with fruit and optional nuts. Serve chilled.'],{methods:['No cooking'],nutIncluded:true,noNutsSeeds:false,ages:['Adults'],poster:'recipe-poster-7',options:[['Dairy-free','Choose coconut cream and explicitly dairy-free chocolate.'],['No added nuts','Omit the nut topping and check all ingredient labels.']]});
R.forEach(r=>{r.productIds ||= [r.productId];r.options ||= [];});
function rdImage(url,alt,cls=''){return `<img class="rd-image ${cls}" src="${url}" alt="${esc(alt)}" loading="lazy" decoding="async">`;}
function recipePhoto(r,cls=''){return rdImage(recipeImageMap[r.id].hero,r.name,cls);}
function recipeHeroArt(r){return recipePhoto(r,'rd-hero-image');}
function recipeCard(r){return `<a class="rd-card" href="/recipes/${r.id}">${recipePhoto(r)}<h3>${r.name}</h3><span class="rd-tag">${r.nonveg?'Non-vegetarian':'Vegetarian'}</span><div class="rd-card-meta"><span>◷ Prep ${r.prep} min${r.chill?' · Plus chilling':r.rest?' · Plus rising':''}</span><span>View recipe →</span></div></a>`;}
const rdHeadings={'cornflakes':'A little crunch. Endless possibilities.','white-oats':'Make more of your mornings.','quick-oats':'Everyday comfort, made your way.','baby-porridge':'Little bowls. Thoughtful beginnings.','cake-mix':'Something worth celebrating.','nutririch-porridge':'Comfort in every spoonful.'};
function recipeGroups(list,selected='',expanded=false){return recipeProducts.filter(p=>!selected||p.id===selected).map(p=>{let group=list.filter(r=>r.productIds.includes(p.id));if(!group.length)return '';const priority={'cornflakes':['berry-cornflakes','cornflake-chicken-bites','cornflake-vegetable-cutlets'],'white-oats':['banana-oat-pancakes','berry-almond-overnight-oats','oat-sourdough-bread']};if(priority[p.id])group.sort((a,b)=>{const rank=x=>{const i=priority[p.id].indexOf(x.id);return i<0?99:i};return rank(a)-rank(b)});const show=selected||expanded?group:group.slice(0,3);return `<section class="rd-group"><div class="rd-group-heading"><div>${eye('MADE WITH '+p.name.toUpperCase())}<h2>${rdHeadings[p.id]||p.name}</h2></div><a href="/recipes?product=${p.id}#recipe-collection">View all ${p.name} recipes →</a></div><div class="rd-grid">${show.map(recipeCard).join('')}</div></section>`;}).join('')||'<div class="rd-empty"><h2>No recipes match these choices.</h2><p>Try a different ingredient or clear your filters.</p></div>';}
function recipeLibrary(){return `<section class="rd-library" id="recipe-collection"><h2>What are you cooking with?</h2><div class="rd-tabs" aria-label="Choose a product"><button data-library-product="" aria-pressed="true">All recipes</button>${recipeProducts.map(p=>`<button data-library-product="${p.id}" aria-pressed="false">${p.name}</button>`).join('')}</div><div class="rd-search"><label><span class="sr-only">Search recipes</span><input type="search" id="recipe-library-search" placeholder="Search for a recipe or ingredient…"></label><button id="rd-filter-toggle" aria-expanded="false" aria-controls="rd-filters">☷ Filters</button><button id="recipe-library-reset">Clear</button></div><div id="rd-filters" hidden><div class="rd-filter-grid">${librarySelect('recipe-age','Age group',[['Kids','Kids'],['Adults','Adults'],['Babies','Babies · pack guidance'],['Older adults','Older adults']])}${librarySelect('recipe-diet','Dietary preference',[['vegetarian','Vegetarian'],['nonveg','Non-vegetarian'],['vegan','Vegan option'],['gf','Gluten-free adaptation'],['dairy','Dairy / dairy-free choice'],['dairy-free','Dairy-free option']])}${librarySelect('recipe-exclusion','Nuts & seeds',[['no-added','No added nuts or seeds'],['nuts','Nuts included'],['seeds','Seeds included']])}${librarySelect('recipe-method','Cooking method',['Air fryer','Oil fry','Oven','Stovetop','Pan cook','No cooking'].map(x=>[x,x]))}</div><p id="recipe-context" class="rd-context">Dietary choices refer to the recipe or its explained variation. Check ingredient labels.</p></div><p id="recipe-library-status" class="rd-status" role="status">${R.length} recipes to explore</p><div id="recipe-library-results">${recipeGroups(R)}</div></section>`;}
function bindRecipeLibrary(){if(!$('#recipe-library-results'))return;let f={};const apply=()=>{const list=R.filter(r=>recipeMatches(r,f));$('#recipe-library-results').innerHTML=recipeGroups(list,f.product,Object.values(f).some(Boolean));$('#recipe-library-status').textContent=`${list.length} recipes${f.product?' in this collection':' to explore'}`;$('#recipe-context').textContent=f.diet==='gf'?gfGuidance:f.age==='Babies'?babyGuidance:allergyGuidance;};$$('[data-library-product]').forEach(b=>b.addEventListener('click',()=>{f.product=b.dataset.libraryProduct;$$('[data-library-product]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));apply();}));for(const [id,key] of [['recipe-age','age'],['recipe-diet','diet'],['recipe-exclusion','exclusion'],['recipe-method','method']])$('#'+id).addEventListener('change',e=>{f[key]=e.target.value;apply()});$('#recipe-library-search').addEventListener('input',e=>{f.q=e.target.value.trim();apply()});$('#rd-filter-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',open);$('#rd-filters').hidden=!open});$('#recipe-library-reset').addEventListener('click',()=>{f={};$$('[data-library-select],#recipe-library-search').forEach(e=>e.value='');$$('[data-library-product]').forEach(b=>b.setAttribute('aria-pressed',String(!b.dataset.libraryProduct)));apply()});const initial=new URLSearchParams(location.search).get('product');if(recipeProducts.some(p=>p.id===initial))$(`[data-library-product="${initial}"]`).click();}
function recipesPage(){document.body.classList.add('rd-page');return `<section class="rd-landing-hero"><div>${eye('THE PROCTOR & ALLAN KITCHEN')}<h1>Good food<br>starts here.</h1><p>Discover delicious ways to enjoy your favourite Proctor & Allan products.</p><a class="rd-button" href="#recipe-collection">Explore recipes ↓</a></div>${rdImage('/assets/recipe-design/cornflakes-hero.webp','Corn flakes with fresh fruit and milk')}</section>`+recipeLibrary()+`<section class="rd-feature">${rdImage('/assets/recipe-design/breakfast-feature.webp','A relaxed breakfast table')}<div>${eye('WEEKEND INSPIRATION')}<h2>Slow mornings.<br>Something delicious.</h2><p>Find your next family breakfast favourite.</p><a class="rd-button" href="/recipes?product=white-oats#recipe-collection">Explore breakfast recipes →</a></div></section>`;}
function recipeDetail(r){document.body.classList.add('rd-page','rd-detail-page');const art=recipeIllustrations[r.id],imgs=recipeImageMap[r.id];const related=R.filter(x=>x.id!==r.id&&x.productId===r.productId).slice(0,2);return `<article class="rd-detail"><nav class="rd-crumb"><a href="/recipes">Recipes</a> / <a href="/recipes?product=${r.productId}">${r.product}</a> / ${r.name}</nav><div class="rd-detail-hero"><div>${eye('FROM OUR '+(r.productId.includes('oat')?'OATS':r.product.toUpperCase())+' KITCHEN')}<h1>${r.name}</h1><p>${r.id==='banana-oat-pancakes'?'Golden edges. Soft centres. A lovely way to start the day.':art?.description||'Enjoy a new way to cook with '+r.product+'. Simple ingredients, something delicious.'}</p><div class="rd-detail-tags"><span class="rd-tag">${r.nonveg?'Non-vegetarian':'Vegetarian'}</span>${r.dairyOption?'<span>Dairy-free variation available</span>':''}</div><div class="rd-actions"><a class="rd-button" href="#recipe-method">Let’s make it ↓</a><button data-print>♧ Print recipe</button></div></div>${recipeHeroArt(r)}</div>${recipeTimingStrip(r)}<div class="rd-ingredients-options"><section class="rd-ingredients"><h2>Everything you’ll need</h2><ul>${r.ingredients.map((t,i)=>{const pi=ingredientPictures.findIndex(p=>p.match.test(t));return `<li><label>${pi>=0?rdImage('/assets/recipe-design/ingredient-'+pi+'.webp',t):'<span class="rd-ingredient-fallback" aria-hidden="true">✧</span>'}<span><input type="checkbox" aria-label="Prepared: ${esc(t)}"> ${esc(t)}</span></label></li>`}).join('')}</ul></section><aside class="rd-options"><h2>Make it your way</h2>${r.options.length?r.options.map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join(''):'<p>Serve as described, or choose toppings to suit your table. Check the ingredient labels before making substitutions.</p>'}</aside></div><section id="recipe-method" class="rd-method"><h2>${r.steps.length===4?'Four simple steps. Something delicious.':'Let’s make something delicious.'}</h2><ol>${r.steps.map((t,i)=>`<li>${imgs.steps[i]?rdImage(imgs.steps[i],(art?.titles[i]||'Step '+(i+1))+' for '+r.name):''}<span class="rd-step-number">${String(i+1).padStart(2,'0')}</span><h3>${art?.titles[i]||'Step '+(i+1)}</h3><p>${esc(t)}</p></li>`).join('')}</ol></section><details class="rd-guidance"><summary>Ingredients, allergens & serving guidance</summary><p>${r.allergens||'Check your current product pack and each ingredient for allergens.'}</p><p>${allergyGuidance}</p>${r.gfOption?`<p>${gfGuidance}</p>`:''}<p>${r.ages.includes('Babies')?babyGuidance:'For children, adapt texture and toppings to their eating abilities. The recipe’s broad audience labels do not establish a minimum serving age.'}</p><p>${r.note||'Timings are estimates. Follow the current product pack and appliance directions.'}</p>${r.poster?`<p><a href="/assets/approved/${r.poster}.webp" target="_blank" rel="noopener">View the original illustrated recipe guide ↗</a></p>`:''}</details><section class="rd-related"><div><h2>Next on your<br>breakfast table</h2><p>More simple recipes to enjoy.</p></div>${related.map(x=>`<a href="/recipes/${x.id}">${recipePhoto(x)}<div><h3>${x.name}</h3><span>View recipe →</span></div></a>`).join('')}</section></article>`;}


function homeRecipeCarousel(){const selected=['cornflake-vegetable-cutlets','banana-oat-pancakes','mango-coconut-overnight-oats','cornflake-chicken-bites','oat-sourdough-bread','berry-almond-overnight-oats','cake-popsicles','savoury-oat-muffins','cornflake-yoghurt-cups'].map(id=>R.find(r=>r.id===id));return `<section class="home-recipe-showcase" id="home-recipes" aria-roledescription="carousel" aria-label="Recipe inspiration"><div class="hr-heading"><div>${eye('THE PROCTOR & ALLAN KITCHEN')}<h2>A little inspiration.<br>Your next favourite.</h2><p>Make more of the foods you love. From quick breakfasts to savoury bites and something sweet, find a recipe to bring everyone to the table.</p></div><a class="btn" href="/recipes/">Explore all recipes <span aria-hidden="true">→</span></a></div><div class="hr-track" tabindex="0" aria-label="Featured recipes">${selected.map((r,i)=>`<article class="hr-card" aria-label="${i+1} of ${selected.length}: ${esc(r.name)}"><a href="/recipes/${r.id}/">${recipePhoto(r)}<span class="hr-product">MADE WITH ${esc(r.product)}</span><h3>${esc(r.name)}</h3><div class="hr-meta"><span>◷ Prep ${r.prep} min${r.chill?' · Plus chilling':r.rest?' · Plus rising':''}</span><span>View recipe →</span></div></a></article>`).join('')}</div><div class="hr-controls"><p>Everyday ingredients. Delicious possibilities.</p><div><button class="hr-prev" aria-label="Previous recipe">←</button><button class="hr-pause" aria-label="Pause automatic recipe rotation" aria-pressed="false">Pause <span aria-hidden="true">Ⅱ</span></button><button class="hr-next" aria-label="Next recipe">→</button></div></div><span class="sr-only hr-status" aria-live="polite"></span></section>`;}
function bindHomeRecipeCarousel(){
 const root=$('.home-recipe-showcase');if(!root)return;
 const track=$('.hr-track',root),cards=$$('.hr-card',root),pause=$('.hr-pause',root),reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let manualPaused=reduced.matches,hover=false,focused=false,frame=0,animating=false,index=0,lastAdvance=performance.now();
 // Repeat the first cards to let the final recipe glide into the first without a rewind.
 cards.slice(0,3).forEach(card=>{const clone=card.cloneNode(true);clone.setAttribute('aria-hidden','true');clone.inert=true;clone.querySelectorAll('a').forEach(a=>a.tabIndex=-1);track.append(clone)});
 const step=()=>cards[0].getBoundingClientRect().width+(parseFloat(getComputedStyle(track).gap)||0);
 function stop(){cancelAnimationFrame(frame);frame=0;animating=false;track.classList.remove('hr-gliding')}
 function move(direction,user=false){
  if(animating)return;
  const width=step(),count=cards.length;
  index=Math.round(track.scrollLeft/width);
  if(index>=count){track.scrollLeft=0;index=0}
  if(direction<0&&index===0){track.scrollLeft=count*width;index=count}
  const from=track.scrollLeft,target=(index+direction)*width;
  lastAdvance=performance.now();
  if(reduced.matches){track.scrollLeft=target;index=(index+direction+count)%count;if(target>=count*width)track.scrollLeft=0}
  else{
   animating=true;track.classList.add('hr-gliding');const start=performance.now(),duration=user?1100:2400;
   function tick(now){const t=Math.min((now-start)/duration,1),ease=t*t*(3-2*t);track.scrollLeft=from+(target-from)*ease;if(t<1){frame=requestAnimationFrame(tick)}else{if(target>=count*width)track.scrollLeft=0;index=(index+direction+count)%count;animating=false;frame=0;track.classList.remove('hr-gliding')}}
   frame=requestAnimationFrame(tick);
  }
  if(user)$('.hr-status',root).textContent='Showing more recipe inspiration';
 }
 function update(){pause.setAttribute('aria-pressed',String(manualPaused));pause.setAttribute('aria-label',manualPaused?'Start automatic recipe rotation':'Pause automatic recipe rotation');pause.innerHTML=manualPaused?'Play <span aria-hidden="true">▷</span>':'Pause <span aria-hidden="true">Ⅱ</span>'}
 $('.hr-prev',root).addEventListener('click',()=>move(-1,true));$('.hr-next',root).addEventListener('click',()=>move(1,true));
 pause.addEventListener('click',()=>{manualPaused=!manualPaused;if(manualPaused)stop();lastAdvance=performance.now();update()});
 root.addEventListener('mouseenter',()=>{hover=true;stop()});root.addEventListener('mouseleave',()=>{hover=false;lastAdvance=performance.now()});
 root.addEventListener('focusin',()=>{focused=true;stop()});root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget)){focused=false;lastAdvance=performance.now()}});
 track.addEventListener('pointerdown',stop);track.addEventListener('wheel',()=>{stop();lastAdvance=performance.now()},{passive:true});
 track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1,true)}});
 const observer=new IntersectionObserver(entries=>{root.dataset.visible=String(entries[0].isIntersecting);if(!entries[0].isIntersecting)stop();lastAdvance=performance.now()},{threshold:.15});observer.observe(root);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();lastAdvance=performance.now()});
 reduced.addEventListener('change',e=>{if(e.matches){manualPaused=true;stop();update()}});
 setInterval(()=>{if(!manualPaused&&!hover&&!focused&&!animating&&!document.hidden&&root.dataset.visible==='true'&&performance.now()-lastAdvance>=9500)move(1)},500);update();
}



